#!/usr/bin/env bash
# Package Trimax-Final.zip (plan.md section 1): code, retained results and the final
# report/slides. File list = tracked + untracked-not-ignored files of the working tree,
# plus the report/slide sources, PDFs and Ada job logs that .gitignore excludes (*.tex,
# *.pdf, *.log). Raw corpora, model checkpoints and per-byte arrays are not included;
# they are regenerated by the pipeline (docs/FINAL_RUN.md, docs/FULL_RUN_RESULTS.md).
#   bash scripts/package_final.sh [out.zip]
set -euo pipefail
cd "$(dirname "$0")/.."
OUT=${1:-Trimax-Final.zip}
if [[ ! -f reports/final_submission/Trimax-Final.pdf || ! -f reports/final_submission/slides/Trimax-Final-Viva.pdf ]]; then
  echo "WARNING: report/slide PDFs not built yet (bash reports/final_submission/build.sh && bash reports/final_submission/build_slides.sh);" >&2
  echo "         packaging sources only -- rerun this script after building the PDFs." >&2
fi
LIST=$(mktemp)
trap 'rm -f "$LIST"' EXIT
git ls-files --cached --others --exclude-standard > "$LIST"
{
  find reports/final_submission -type f \( -name '*.tex' -o -name '*.pdf' -o -name '*.bib' -o -name '*.sty' -o -name '*.bst' \
       -o -path '*/generated/*' -o -path '*/validation/*' \) ! -path '*/build/*'
  find reports/mid_submission -maxdepth 1 -type f \( -name '*.tex' -o -name '*.pdf' \)
  find reports -maxdepth 1 -type f -name '*.pdf'
  find results/final/logs -type f
} >> "$LIST"
sort -u "$LIST" | grep -v -E '^(Trimax-Final\.zip|plan\.md|file_toimplement\.md)$' | while read -r f; do [[ -f "$f" ]] && echo "$f"; done > "$LIST.ok"
rm -f "$OUT"
zip -q -X "$OUT" -@ < "$LIST.ok"
rm -f "$LIST.ok"
echo "wrote $OUT: $(unzip -l "$OUT" | tail -1 | awk '{print $2}') files, $(du -h "$OUT" | cut -f1)"
